<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';
rh24_require_login();
if(!rh24_can('print_labels')){http_response_code(403);exit('Keine Berechtigung zum Etikettendruck.');}
rh24_label_ensure_ready();
$id=trim((string)($_GET['id']??''));
$job=rh24_label_job_detail($id);
$db=rh24_db();
$q=$db->prepare('SELECT * FROM label_templates WHERE id=?');$q->execute([$job['template_id']]);$tpl=$q->fetch();if(!$tpl)exit('Vorlage nicht gefunden.');
$printer=null;if(!empty($job['printer_id'])){$q=$db->prepare('SELECT * FROM label_printers WHERE id=?');$q->execute([$job['printer_id']]);$printer=$q->fetch()?:null;}
$media=null;$mediaId=trim((string)($job['payload']['media_id']??''));if($mediaId!==''){$q=$db->prepare("SELECT * FROM label_media WHERE id=? AND status='active'");$q->execute([$mediaId]);$media=$q->fetch()?:null;}
$layout=rh24_json_decode((string)$tpl['layout_json'],[]);$override=is_array($job['payload']['layout_override']??null)?$job['payload']['layout_override']:[];$layout=array_replace($layout,$override);
$w=(float)$tpl['width_mm'];$h=(float)$tpl['height_mm'];$orientation=(string)$tpl['orientation'];if($orientation==='portrait'&&$w>$h){[$w,$h]=[$h,$w];}
$ms=$media?rh24_json_decode((string)($media['settings_json']??''),[]):[];$mediaProfileKind=(string)($media['media_kind']??'');if($media&&in_array($mediaProfileKind,['diecut_roll','diecut_sheet'],true)){$w=(float)$media['width_mm'];$h=(float)$media['height_mm'];}elseif($media&&$mediaProfileKind==='continuous_roll'){$w=(float)$media['width_mm'];$targetH=(float)$media['height_mm'];if(($ms['length_mode']??'auto')==='fixed')$h=$targetH;else{$ratio=max(.25,min(4.0,$h/max(1,$w)));$h=max(12,min(500,$targetH>0?$targetH:$w*$ratio));}}
$theme=preg_replace('/[^a-z0-9_-]/i','',(string)($layout['theme']??'classic'))?:'classic';
$accent=(string)($layout['accent']??'#b8441b');if(!preg_match('/^#[0-9a-f]{6}$/i',$accent))$accent='#b8441b';
function h(string $s): string{return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
function price(mixed $v): string{return number_format((float)$v,2,',','.').' €';}
function nmm(float $v): string{return rtrim(rtrim(number_format($v,2,'.',''),'0'),'.');}
$labels=[];foreach($job['items'] as $it){for($i=0;$i<max(1,(int)$it['copies']);$i++)$labels[]=$it['data'];}
$ps=$printer?rh24_json_decode((string)($printer['settings_json']??''),[]):[];$manufacturer=strtolower((string)($printer['manufacturer']??''));
$sheetDefault=in_array($manufacturer,['hp','generic','epson','canon','lexmark','xerox','avery zweckform'],true);
if($media){$mk=(string)$media['media_kind'];$ps['media_kind']=in_array($mk,['diecut_sheet','plain_sheet'],true)?'sheet':'label_roll';if(!empty($media['paper_size']))$ps['paper_size']=(string)$media['paper_size'];if(isset($ms['margin_mm']))$ps['margin_mm']=$ms['margin_mm'];if(isset($ms['gap_x_mm']))$ps['gap_x_mm']=$ms['gap_x_mm'];if(isset($ms['gap_y_mm']))$ps['gap_y_mm']=$ms['gap_y_mm'];$ps['selected_media_kind']=$mk;}
$mediaKind=(string)($ps['media_kind']??($sheetDefault?'sheet':'label_roll'));
$paperSize=(string)($ps['paper_size']??'A4');$pageOrientation=(string)($ps['page_orientation']??'portrait');$margin=max(0,min(40,(float)($ps['margin_mm']??8)));$marginX=$margin;$marginY=$margin;$gapX=max(0,min(30,(float)($ps['gap_x_mm']??3)));$gapY=max(0,min(30,(float)($ps['gap_y_mm']??3)));$fitMode=(string)($ps['fit_mode']??'auto');$autoRotate=($ps['auto_rotate']??true)!==false;$center=($ps['center_on_page']??true)!==false;
$paperMap=['A4'=>[210.0,297.0],'A5'=>[148.0,210.0],'A6'=>[105.0,148.0],'Letter'=>[215.9,279.4]];
[$paperW,$paperH]=$paperMap[$paperSize]??[(float)($ps['paper_width_mm']??210),(float)($ps['paper_height_mm']??297)];
if($pageOrientation==='landscape'&&$paperH>$paperW){[$paperW,$paperH]=[$paperH,$paperW];}if($pageOrientation==='portrait'&&$paperW>$paperH){[$paperW,$paperH]=[$paperH,$paperW];}
$rotated=false;$scale=1.0;$cols=1;$rows=1;$perPage=1;$slotW=$w;$slotH=$h;
if($mediaKind==='sheet'){
  $fixedGrid=$media&&$mediaProfileKind==='diecut_sheet'&&(int)$media['cols']>0&&(int)$media['rows']>0;
  if($fixedGrid){
    $cols=max(1,(int)$media['cols']);$rows=max(1,(int)$media['rows']);$perPage=$cols*$rows;$slotW=$w;$slotH=$h;$scale=1.0;$rotated=false;$gapX=max(0,(float)($ms['gap_x_mm']??0));$gapY=max(0,(float)($ms['gap_y_mm']??0));$usedW=$cols*$slotW+($cols-1)*$gapX;$usedH=$rows*$slotH+($rows-1)*$gapY;$marginX=max(0,($paperW-$usedW)/2+(float)($ms['calibration_x_mm']??0));$marginY=max(0,($paperH-$usedH)/2+(float)($ms['calibration_y_mm']??0));
  }else{
    $availW=max(1,$paperW-2*$marginX);$availH=max(1,$paperH-2*$marginY);
    $calc=function(float $lw,float $lh)use($availW,$availH,$gapX,$gapY,$fitMode):array{$sc=1.0;if($fitMode!=='actual'&&($lw>$availW||$lh>$availH))$sc=min($availW/$lw,$availH/$lh);$ew=$lw*$sc;$eh=$lh*$sc;$c=max(1,(int)floor(($availW+$gapX)/($ew+$gapX)));$r=max(1,(int)floor(($availH+$gapY)/($eh+$gapY)));return ['lw'=>$lw,'lh'=>$lh,'scale'=>$sc,'w'=>$ew,'h'=>$eh,'cols'=>$c,'rows'=>$r,'per'=>$c*$r];};
    $best=$calc($w,$h);if($autoRotate){$r=$calc($h,$w);if($r['per']>$best['per']){$best=$r;$rotated=true;}}
    $scale=(float)$best['scale'];$slotW=(float)$best['w'];$slotH=(float)$best['h'];$cols=(int)$best['cols'];$rows=(int)$best['rows'];$perPage=max(1,(int)$best['per']);
  }
}else{$paperW=$w;$paperH=$h;$margin=0;$marginX=0;$marginY=0;$gapX=0;$gapY=0;}
$pages=$mediaKind==='sheet'?array_chunk($labels,$perPage):array_map(fn($x)=>[$x],$labels);
function label_html(array $d,array $layout,array $tpl,string $theme,string $accent,bool $reprint,float $baseW,float $baseH,float $scale,bool $rotated): string {
  $name=(string)($d['name']??$d['company']??$d['customer_name']??'Etikett');$barcodeField=(string)($layout['barcode_field']??'barcode');$code=(string)($d[$barcodeField]??$d['barcode']??$d['sku']??$d['order_no']??'');$bc=(string)($layout['barcode']??'code128');$ship=in_array((string)$tpl['category'],['shipping','address'],true);$extra=[];
  if(!empty($layout['show_category'])&&!empty($d['category']))$extra[]='Kategorie: '.(string)$d['category'];if(!empty($layout['show_minimum']))$extra[]='Min. Bestand: '.(string)($d['minimum']??0);if(!empty($layout['show_batch']))$extra[]='Charge: '.(string)($d['batch']??'CH-…');if(!empty($layout['show_best_before']))$extra[]='MHD: '.(string)($d['best_before']??'TT.MM.JJJJ');if(!empty($layout['show_origin']))$extra[]='Herkunft: '.(string)($d['origin']??'Deutschland');if(!empty($layout['show_weight']))$extra[]='Gewicht: '.(string)($d['weight']??$d['unit']??'');if(!empty($layout['show_date']))$extra[]='Datum: '.date('d.m.Y');if(!empty($layout['show_note'])&&!empty($d['note']))$extra[]=(string)$d['note'];
  $fontScale=max(.7,min(1.5,(float)($layout['font_scale']??1)));$nameScale=max(.7,min(2.2,(float)($layout['name_scale']??1)));$priceScale=max(.7,min(2.5,(float)($layout['price_scale']??1)));$metaScale=max(.7,min(1.8,(float)($layout['meta_scale']??1)));$barcodeScale=max(.7,min(1.6,(float)($layout['barcode_scale']??1)));
  $html='<section class="label theme-'.h($theme).($ship?' ship':'').($rotated?' adapted':'').'" style="--accent:'.h($accent).';--base-w:'.nmm($baseW).'mm;--base-h:'.nmm($baseH).'mm;--content-scale:'.$scale.';--font-scale:'.$fontScale.';--name-scale:'.$nameScale.';--price-scale:'.$priceScale.';--meta-scale:'.$metaScale.';--barcode-scale:'.$barcodeScale.'">';
  if($reprint)$html.='<span class="reprint">NACHDRUCK</span>';if(!empty($layout['badge']))$html.='<div class="badge">'.h((string)$layout['badge']).'</div>';if(!empty($layout['show_logo']))$html.='<div class="brand">Räucherhaken24</div>';
  if($ship){$html.='<div class="name">'.h($name).'</div><div class="address">'.h((string)($d['street']??'')).'<br>'.h(trim((string)($d['zip']??'').' '.(string)($d['city']??''))).'<br>'.h((string)($d['country']??'Deutschland')).'</div>';if(!empty($d['order_no']))$html.='<div class="meta">Auftrag '.h((string)$d['order_no']).(!empty($d['carrier'])?' · '.h((string)$d['carrier']):'').'</div>';if(!empty($layout['show_tracking'])&&!empty($d['tracking']))$html.='<div class="meta">Tracking '.h((string)$d['tracking']).'</div>';if(!empty($layout['show_note'])&&!empty($d['note']))$html.='<div class="extra">'.h((string)$d['note']).'</div>';
  }else{if(!empty($layout['show_name']))$html.='<div class="name">'.h($name).'</div>';$meta='';if(!empty($layout['show_sku']))$meta.='Art. '.h((string)($d['article_no']??$d['sku']??'')).'<br>';if(!empty($layout['show_unit'])&&!empty($d['unit']))$meta.=h((string)$d['unit']);if(!empty($layout['show_location'])&&!empty($d['location']))$meta.=' Lager: '.h((string)$d['location']);$html.='<div class="row"><div class="meta">'.$meta.'</div>';if(!empty($layout['show_price']))$html.='<div class="price">'.price($d['price']??0).(!empty($layout['show_vat'])?'<small>inkl. MwSt.</small>':'').'</div>';$html.='</div>';if(!empty($layout['show_stock']))$html.='<div class="stock">Bestand '.h((string)($d['stock']??0)).'</div>';if($extra)$html.='<div class="extra">'.implode('<br>',array_map('h',$extra)).'</div>';}
  if($code!==''&&$bc!=='none')$html.='<div class="barcodeWrap '.(!empty($layout['barcode_emphasis'])?'emphasis':'').'"><canvas class="barcode" data-bc="'.h($bc).'" data-code="'.h($code).'"></canvas><span class="codeFallback">'.h($code).'</span></div>';
  return $html.'</section>';
}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h((string)$job['job_no'])?> · Etiketten</title>
<style>
@page{size:<?=nmm($paperW)?>mm <?=nmm($paperH)?>mm;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#e9e4df;font-family:Arial,Helvetica,sans-serif;color:#171310}.toolbar{position:sticky;top:0;z-index:20;background:linear-gradient(90deg,#211713,#4d2b1e);color:#fff;padding:11px 15px;display:flex;gap:9px;align-items:center;box-shadow:0 5px 20px #0002}.toolbar button{border:0;border-radius:10px;padding:10px 15px;font-weight:800;cursor:pointer}.toolbar .primary{background:#d45b28;color:#fff}.toolbar .paperInfo{display:flex;gap:6px;flex-wrap:wrap}.toolbar .paperInfo span{font-size:10px;padding:5px 8px;border-radius:999px;background:#ffffff18;border:1px solid #ffffff20}.toolbar small{opacity:.72;margin-left:auto}.pages{padding:18px;display:flex;flex-direction:column;align-items:center;gap:18px}.printPage{width:<?=nmm($paperW)?>mm;height:<?=nmm($paperH)?>mm;background:#fff;page-break-after:always;break-after:page;position:relative;overflow:hidden;box-shadow:0 12px 34px #0002}.sheetGrid{position:absolute;left:<?=nmm($marginX)?>mm;right:<?=nmm($marginX)?>mm;top:<?=nmm($marginY)?>mm;bottom:<?=nmm($marginY)?>mm;display:grid;grid-template-columns:repeat(<?=$cols?>,<?=nmm($slotW)?>mm);grid-auto-rows:<?=nmm($slotH)?>mm;gap:<?=nmm($gapY)?>mm <?=nmm($gapX)?>mm;<?=$center?'justify-content:center;align-content:center;':'justify-content:start;align-content:start;'?>}.slot{width:<?=nmm($slotW)?>mm;height:<?=nmm($slotH)?>mm;overflow:hidden;position:relative}.label{width:100%;height:100%;background:#fff;position:relative;overflow:hidden;padding:2.2mm;border:.15mm solid #e7e2dc;display:flex;flex-direction:column;justify-content:space-between}.slot .label{font-size:calc(10pt * <?=max(.55,min(1.0,$scale))?>)}.label:before{content:"";position:absolute;left:0;top:0;bottom:0;width:.8mm;background:var(--accent)}.brand{font-size:2.3mm;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}.name{font-size:calc(3.4mm * var(--font-scale,1) * var(--name-scale,1));line-height:1.03;font-weight:900;max-height:12mm;overflow:hidden}.meta{font-size:calc(2.1mm * var(--font-scale,1) * var(--meta-scale,1));line-height:1.2;color:#5c554f}.price{font-size:calc(5mm * var(--font-scale,1) * var(--price-scale,1));line-height:.95;font-weight:900;color:var(--accent)}.price small{display:block;font-size:1.4mm;font-weight:700;color:#6a625c;margin-top:.6mm}.barcodeWrap{display:flex;align-items:flex-end;gap:1.5mm;min-height:calc(10mm * var(--barcode-scale,1));transform:scale(var(--barcode-scale,1));transform-origin:left bottom;max-width:calc(100% / var(--barcode-scale,1))}.barcodeWrap canvas{max-width:100%;height:auto;max-height:calc(11mm * var(--barcode-scale,1))}.barcodeWrap.emphasis{min-height:14mm}.barcodeWrap.emphasis canvas{max-height:14mm}.codeFallback{font-family:monospace;font-size:1.8mm;word-break:break-all}.ship .name{font-size:3mm}.address{font-size:2.5mm;line-height:1.25;font-weight:700}.stock{font-size:4.6mm;font-weight:900}.row{display:flex;justify-content:space-between;gap:2mm;align-items:flex-end}.tiny{font-size:1.8mm}.extra{font-size:calc(1.8mm * var(--font-scale,1) * var(--meta-scale,1));line-height:1.25;color:#514942}.badge{align-self:flex-start;background:var(--accent);color:#fff;border-radius:99mm;padding:.8mm 1.5mm;font-size:1.55mm;font-weight:900;letter-spacing:.06em}.reprint{position:absolute;right:2mm;top:1mm;font-size:1.5mm;color:#999}.theme-minimal:before,.theme-clean:before{display:none}.theme-premium{border:.45mm solid var(--accent);background:linear-gradient(145deg,#fffdf9,#f7f1e7)}.theme-sale,.theme-warning{border:.55mm solid var(--accent)}.theme-sale .price,.theme-price_xl .price,.theme-price_only .price{font-size:7mm}.theme-warehouse .stock,.theme-warehouse_xl .stock{color:var(--accent)}.theme-business{border-top:1.2mm solid var(--accent)}.theme-gift{background:#fff7fb}.theme-food{background:#fffdf4}.rollPage .label{border:0;width:100%;height:100%}
@media print{html,body{background:#fff}.toolbar{display:none}.pages{display:block;padding:0}.printPage{box-shadow:none;margin:0;page-break-after:always;break-after:page}.label.theme-premium,.label.theme-sale,.label.theme-warning{border:.45mm solid var(--accent)}}
</style><script src="https://cdn.jsdelivr.net/npm/bwip-js@4.11.2/dist/bwip-js-min.js"></script></head><body>
<div class="toolbar"><button class="primary" onclick="window.print()">Drucken</button><button onclick="history.back()">Zurück</button><div class="paperInfo"><span><?=h((string)$job['job_no'])?></span><span><?=count($labels)?> Etikett(e)</span><span><?=h((string)$tpl['name'])?></span><?php if($media):?><span><?=h((string)$media['name'])?></span><?php endif;?><span><?=h($mediaKind==='sheet'?$paperSize.' · '.$cols.'×'.$rows.' = '.$perPage.'/Seite':'Rollenformat '.nmm($w).'×'.nmm($h).' mm')?></span><?php if($scale<.999):?><span><?=round($scale*100)?> % angepasst</span><?php endif;?></div><small>Im Druckdialog: Maßstab 100 % · Kopf/Fußzeile aus</small></div>
<main class="pages">
<?php foreach($pages as $page):?>
<section class="printPage <?=$mediaKind==='sheet'?'sheetPage':'rollPage'?>">
<?php if($mediaKind==='sheet'):?><div class="sheetGrid"><?php foreach($page as $d):?><div class="slot"><?=label_html($d,$layout,$tpl,$theme,$accent,!empty($_GET['reprint']),$w,$h,$scale,$rotated)?></div><?php endforeach;?></div><?php else:?><?=label_html($page[0],$layout,$tpl,$theme,$accent,!empty($_GET['reprint']),$w,$h,1,false)?><?php endif;?>
</section>
<?php endforeach;?>
</main><script>
const LABEL_JOB_ID=<?=json_encode($id,JSON_UNESCAPED_SLASHES)?>;const LABEL_CSRF=<?=json_encode(rh24_csrf(),JSON_UNESCAPED_SLASHES)?>;
window.addEventListener('load',()=>{document.querySelectorAll('canvas.barcode').forEach(c=>{if(!window.bwipjs)return;let b=c.dataset.bc||'code128';if(b==='qrcode')b='qrcode';else if(b==='ean13'&&!/^\d{13}$/.test(c.dataset.code||''))b='code128';try{bwipjs.toCanvas(c,{bcid:b,text:c.dataset.code||'',scale:2,height:b==='qrcode'?12:7,includetext:b!=='qrcode',textxalign:'center',backgroundcolor:'FFFFFF'});c.nextElementSibling.style.display='none'}catch(e){console.warn('Barcode fallback',e)}})});
window.addEventListener('afterprint',()=>{fetch('label-api.php?v=96.5',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':LABEL_CSRF},body:JSON.stringify({action:'job_mark_printed',id:LABEL_JOB_ID})}).catch(()=>{})});
</script></body></html>
